import{_ as i,l as n,o,c as l,v as a,p as r,x as t,d as c,i as s,S as k}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"流式 detokenize 边界","description":"","frontmatter":{"title":"流式 detokenize 边界","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/streaming-detokenize.md","filePath":"llm/streaming-detokenize.md","lastUpdated":1789023840000}'),p={name:"llm/streaming-detokenize.md"};function E(m,e,h,B,T,A){const d=n("Mermaid");return o(),l("div",null,[e[1]||(e[1]=a('<h1 id="流式-detokenize-边界" tabindex="-1">流式 detokenize 边界 <a class="header-anchor" href="#流式-detokenize-边界" aria-label="Permalink to &quot;流式 detokenize 边界&quot;">​</a></h1><div class="epigraph"><p>Token 不是字符：一个片可能是半个 UTF-8 码点，也可能跨过词的边界；过早把字节刷给客户端，会打出替换符或把词切成两次闪烁。</p><footer>—— Sennrich et al., Neural Machine Translation of Rare Words with Subword Units, ACL 2016；实现对照 HuggingFace TextStreamer 与 tiktoken 的增量解码</footer></div><p><a href="/llm/jacobi-decoding">上一课</a>在 token 空间并行猜。产品交付的是字符串，而且是 <em>边生成边推</em>。本课补 token 与 Unicode 之间的缝：detokenize 不能每来一个 id 就 <code>decode</code> 一次并立刻发送。BPE / byte-level BPE 下，未完成的 UTF-8 序列、尚未合并的尾片、以及带空格标记的片，都会让增量解码与整段解码不一致。后课的采样器内核仍在 id 空间；本课把字符串边界钉死，避免把 UI 闪烁当成模型问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>训练与评测都在完整序列上 <code>tokenizer.decode(ids)</code>。流式把 <code>ids[:k]</code> 的解码结果当已交付文本，假设它是 <code>decode(ids)</code> 的前缀。该假设对字符级词表成立，对 BPE 不成立：下一个 token 可能改写最后一个码点（byte-level 下续上 UTF-8 尾字节），或吞掉一个尚未显示的空格标记。缺口是增量协议：哪些后缀是 <em>稳定前缀</em>，可以发给客户端；哪些必须缓冲，直到再来一个 token 或遇到 EOS。</p><p>另一类边界是多字节标点与 CJK：一个汉字常是一个 token，看起来没有问题；英文 <code>ing</code> 后缀却可能把已显示的 <code>runn</code> 变成 <code>running</code>，若 UI 已画出 <code>runn</code>，只能闪烁改写。协议应允许「替换最后一段未稳定后缀」，或等到稳定再发。</p><p><span class="marginnote">n-gram 阻断在 token 空间；用户看见的重复在字符串空间。两者对不齐时，会出现「模型没重复 token、屏幕上重复了词」或反过来。日志应同时存 id 与稳定字符串。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>维护字节缓冲。每来一个 token，先转换成字节（byte-level BPE）或拼到暂定 Unicode 串，然后：</p><ul><li>若缓冲末尾是未完成 UTF-8，不发送，等后续 token。</li><li>若分词器带 <code>Ġ</code> / <code>▁</code> 一类前缀空格标记，只有当空格已经确定属于已完成词，才把上一个词标为稳定。</li><li>对客户端提供两种帧：<code>append</code> 稳定前缀，<code>replace_tail</code> 修正未稳定后缀。SSE / WebSocket 必须声明哪一种；只支持 append 的网关只能延迟发送。</li></ul><p>停止词、JSON 括号匹配若在字符串上做，必须用 <em>已稳定</em> 前缀，不能用含半个码点的缓冲，否则会误触发。约束解码的掩码仍在 token 空间，不要用字符串停止词替代文法。</p>',11)),(o(),r(k,null,{default:t(()=>[s(d,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20ID%5B%22%E6%96%B0%20token%20id%22%5D%20--%3E%20BYTES%5B%22%E6%8B%BC%E8%BF%9B%E5%AD%97%E8%8A%82%E7%BC%93%E5%86%B2%22%5D%0A%20%20BYTES%20--%3E%20UTF%7B%22UTF-8%20%E5%AE%8C%E6%95%B4%3F%22%7D%0A%20%20UTF%20--%3E%7C%E5%90%A6%7C%20HOLD%5B%22%E7%BB%A7%E7%BB%AD%E7%BC%93%E5%86%B2%22%5D%0A%20%20UTF%20--%3E%7C%E6%98%AF%7C%20STAB%7B%22%E8%AF%8D%E8%BE%B9%E7%95%8C%E7%A8%B3%E5%AE%9A%3F%22%7D%0A%20%20STAB%20--%3E%7C%E5%90%A6%7C%20TAIL%5B%22replace_tail%20%E5%80%99%E9%80%89%22%5D%0A%20%20STAB%20--%3E%7C%E6%98%AF%7C%20SEND%5B%22append%20%E7%BB%99%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>整段 <code>decode</code> 通常会在末尾做一次「尽量解释」的容错；增量路径若每步都走容错，就会把半序列解释成 <code>�</code> 再在下一步撤回。正确的增量解码器与 tiktoken / HuggingFace 的 stream decoder 一样：内部状态机记住未完成字节，绝不把非法 UTF-8 当字符发出。投机与 Jacobi 若一次提交 \\(k\\) 个 token，应按批跑增量状态，而不是 \\(k\\) 次独立 <code>decode</code>——后者会把中间不稳定态泄漏到网上。</p><p><a href="/llm/kv-layout">KV 布局</a>与 detokenize 无关：缓存里没有字符串。但流式 TTS / 终端 UI 的延迟会把「先等一个 token 再发」放大成可感知卡顿；权衡是稳定 vs TTFT 字符串。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在网关用 Python <code>tokenizer.decode(ids[:k])</code> 每 token 一次当协议。不要把替换符发给用户再删除。工具调用的 JSON 解析应对稳定前缀做增量 parse，半个字符串 token 不是合法 JSON。多语言混合时，byte-level 与 sentencepiece 的稳定规则不同，转换检查点必须换对应解码器。</p><p>出处：Sennrich et al., ACL 2016；增量行为以 tiktoken 与 HuggingFace <code>TextIteratorStreamer</code> 的实现为准。无单独「流式 detokenize」会议论文，不编造。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>流式可发送的是稳定前缀，不是每个 id 的即时 <code>decode</code>。</li><li>未完成 UTF-8 与未定空格标记必须缓冲或允许改尾。</li><li>停止词与 JSON 只认稳定字符串；掩码仍在 token 空间。</li><li>一次提交多 token 时按批走增量状态机。</li><li>UI 闪烁往往是协议只支持 append。</li><li>后课回到 GPU：采样器本身也是内核。</li><li>出处：Sennrich et al., ACL 2016；HuggingFace / tiktoken 增量解码实现。</li></ul>',8))])}const S=i(p,[["render",E]]);export{_ as __pageData,S as default};
